    "chore.hoover.give":["mom","The vacuum's in the cupboard under the stairs. Every crumb, please."],
    "chore.hoover.done":["mom","Spotless. You can see the stripes."],
    "chore.videos.give":["mom","The videos are all over the floor. Back on the shelf, and rewind them. Be kind."],
    "chore.videos.done":["mom","That's better. I can find the film I want now."],
    "chore.cushions.give":["mom","The cushions, please. Plump them. On their corners, like diamonds."],
    "chore.cushions.done":["mom","Like diamonds. Very good."],
    "chore.car.give":["mom","Your father's car is a disgrace. Bucket, sponge, rinse. Watch out for the pigeon."],
    "chore.car.done":["mom","It's shining. Your father will be thrilled. And suspicious."],
    "chore.lawn.give":["mom","The front lawn. Straight stripes, please. Mind the cable. Mind the gnome."],
    "chore.lawn.done":["mom","Stripes like a cricket pitch. Very smart."],
    "chore.sweep.give":["mom","The drive's covered in leaves. Brush them up, dustpan, dustbin."],
    "chore.sweep.done":["mom","Lovely and tidy. The neighbours will be jealous."],
    "c1.lad.sis.in":["sister","Ooh, what are you playing? Can I have a go? Go on, go on, go on!",null,"sis-whine"],
    "c1.lad.sis.no":["sister","You never let me do anything! I'm telling!",null,"sis-whine"],
    "c1.lad.sis.out":["sister","I'm telling Mom it's all your fault anyway."],
    "c1.sis.stairs":["sister","Is that a computer? Is it mine? I want a go! It's not fair!",null,"sis-whine"],
    "c1.sis.stairs2":["sister","Fine. I'll just sit on the stairs and watch."],
    "c1.logon.sis":["sister","Wow. Can I come in? Pleeeease? When can I have a go?",null,"sis-whine"],
    "c2.sell.sis":["sister","That's mine! You said I could have that!",null,"sis-whine"],
    "c2.sell.sold":["sister","Ha ha, someone bought your teddy."],
    "c2.post.sis":["sister","Mom! Mom! Something's come! It's a big box!"],
    "c2.unbox.sis":["sister","Can I carry it? I'll be really careful. Promise."],
    "c2.play.sis":["sister","Whoa. Is that the actual game? It looks like a film!"],
    "c3.cable.sis":["sister","What's that for? Is it a skipping rope?"],
    "c3.mag.sis":["sister","I've had a look at the pictures, and it's got a free sticker. I'm having the sticker."],
    "c3.run.trip.sis":["sister","Whoa! Nobody told me about the wire!"],
    "c3.dial.sis":["sister","Whoa. That's the loudest noise I've ever heard."],
    "c4.mag.sis":["sister","Is that the new one? Let me see! Let me see!"],
    "c4.tourney.sis":["sister","I want to play! I'll be quiet! I'll be good! Pleeease!",null,"sis-whine"],
    "c4.dd.sis":["sister","Can I have a go when you get it? I'll be really good. I'll do your jobs."],
    "c4.dd.parcel":["sister","IT'S HERE! IT'S HERE! IT'S THE BIG ONE!",null,"sis-whine"],
    "c4.dd.first":["sister","It's so shiny. It looks like a real film."],
    "c4.hal.sis":["sister","Wooooo! I'm a ghost! Do I look scary? Say yes."],
    "c4.hal.night2":["sister","I'm not scared. I'm just hiding. For fun."],
    "c4.bon.sis":["sister","Look! I'm writing in the air! Can you read it?"],
    "c4.xmas.sis":["sister","Can I put the star on? Can I? Can I? It's my turn this year!"],
    "c4.xmas.morn":["sister","HE'S BEEN! HE'S BEEN! GET UP! GET UP!",null,"sis-whine"],
    "c4.mill.sis":["sister","Can I stay up until midnight? Pleeease? It's the millennium!"],
    "c4.mill.sis.cheer":["sister","It's the new millennium! It's the future!"],
    "bark.sis.tea1":["sister","I don't like the green bits. Can I have just the orange bits?"],
    "bark.sis.tea2":["sister","Can I leave the table? I've finished. I mean I've pushed it round."],
    "bark.sis.tea3":["sister","They're looking at me! Mom, they're looking at me!"],
    "bark.sis.line1":["sister","I'll get it! I'll get it! Hello? Who's calling?"],
    "bark.sis.line2":["sister","Mom, it's for you. Someone who talks a lot."],
    "bark.sis.tv1":["sister","I want cartoons! It's my turn! You had it yesterday!",null,"sis-whine"],
    "bark.sis.tv2":["sister","I can't hear it. Turn it up. Turn it UP.",null,"sis-whine"],
    "bark.sis.mess1":["sister","Mom! They left their socks in the lounge again!"],
    "bark.sis.mess2":["sister","I tidied my room. Look. I've done everything. Where's my pound?"],
    "bark.sis.bed1":["sister","I'm not tired! I don't wanna go to bed!"],
    "bark.sis.bed2":["sister","Can I have a drink of water? And a story? And the landing light?"],
    "bark.sis.school1":["sister","I can't find my shoe. It was right there. Someone moved it."],
    "bark.sis.school2":["sister","I don't wanna go. I've got a spelling test."],
    "bark.sis.wknd1":["sister","Cartoons! Saturday morning telly! The best!"],
    "bark.sis.wknd2":["sister","Can we go to the park? Can we? Pleeease?"],
    "bark.sis.cut1":["sister","Mom? It's dark! I don't like it!"],
    "bark.sis.cut2":["sister","They're back! It's magic!"],
    "bark.sis.react.lounge":["sister","Nobody ever plays with me!",null,"sis-whine"],
    "bark.sis.react.peek":["sister","I'm not spying. I'm just standing here. Normally."],
    "bark.sis.react.drawing":["sister","Look at my picture! It's a dog. Or a horse. You choose.",null,"sis-whine"],
    "bark.sis.react.console":["sister","Can I be player two? I'll let you win. Maybe.",null,"sis-whine"],
