    "chore.shout.bdi29n":["mom","Good helper!"],
    "chore.shout.y5q1ps":["mom","Have you done your jobs yet?",null,"mom-shout"],
    "chore.shout.zuxo6x":["mom","Ta, love!"],
    "dialer.01632960777.1wxgtgo":["mom","Have you done your homework?",null,"mom-call"],
    "dialer.01632960777.n7bz0i":["mom","Hello? Is everything alright? You're not on the Internet, are you? I can't ring home when you're on the Internet!"],
